# 将 ___ 替换为你的代码

class MinHeap:
    def __init__(self):
        self.heap = []
    # 返回堆中节点的数量
    def size(self):
            return len(self.heap)

    # 检查堆是否为空
    def is_empty(self):
        return len(self.heap) == 0

    # 堆的字符串表示形式
    def __str__(self):
        return str(self.heap)

    # 交换堆值
    def swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    # 计算节点的父节点的索引
    def parent(self, index):
        return (index - 1) // 2

    # 计算节点的左孩子的索引
    def left_child(self, index):
        return 2 * index + 1

    # 计算节点的右孩子的索引
    def right_child(self, index):
        return 2 * index + 2

    # 检查给定索引的节点是否有父节点
    def has_parent(self, index):
        return self.parent(index) >= 0

    # 检查给定索引的节点是否有左孩子
    def has_left_child(self, index):
        return self.left_child(index) < len(self.heap)

    # 检查给定索引的节点是否有右孩子
    def has_right_child(self, index):
        return self.right_child(index) < len(self.heap)

    def insert(self, value):
        self.heap.append(value)
        index = len(self.heap) - 1
        while self.has_parent(index) and self.heap[index] < self.heap[self.parent(index)]:
            parent_index = self.parent(index)
            self.swap(index, parent_index)
            index = parent_index

    # 从堆中删除
    def extract_min(self):
        min = self.heap[0]
        # 如果堆有一或零个元素，就使数组为空
        if self.size() == 1:    
            self.heap = []
            return min

        # 将根节点替换为最后一个节点
        self.heap[0] = self.heap[-1] 
        self.heap.pop()  

        index = 0
        while True:
            # 如果到达叶节点，就跳出循环
            if not self.has_left_child(index):
                break

            # 找到较小的子节点索引
            smaller_child_index = self.left_child(index)
            if self.has_right_child(index): 
                if self.heap[self.right_child(index)] < self.heap[self.left_child(index)]:
                    smaller_child_index = self.right_child(index)

            # 比较节点和其较小的孩子，如果需要就交换
            if self.heap[index] > self.heap[smaller_child_index]:
                self.swap(index, smaller_child_index)

            # 如果满足堆属性，就跳出循环
            else:
                break  

            index = smaller_child_index
        return min

# 示例用法:
heap = MinHeap()
array = [1, 2, 5, 3, 4, 6, 7]
for i in array:
    heap.insert(i)
print(f'Root: {heap.extract_min()}')
print(heap)
